import { loadFont as loadSerif } from "@remotion/google-fonts/Cinzel";
import { loadFont as loadSans } from "@remotion/google-fonts/Inter";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, interpolate, staticFile, useCurrentFrame } from "remotion";
import { AME3_CUTS } from "./AmeEdicao3";

// AME · 3ª edição do Passarela Empreendedora, versão só com lettering (pedido, 12/10): sem cenas de motion.
// Ela fica na tela o tempo todo (o mesmo vídeo sem as pausas, public/ame/ame3-cut.mp4), com aproximação diferente a
// cada frase; as fotos da edição anterior entram em tela cheia quando ela fala do evento. Um degradê escuro leve em
// cima e embaixo segura o texto. Lettering na identidade da AME: Inter branco, destaque em Cinzel dourado.
// Todos os tempos = tempo da fala no vídeo original; toSrc converte o tempo do vídeo final.

const { fontFamily: CZ } = loadSerif("normal", { weights: ["700"], subsets: ["latin", "latin-ext"] });
const { fontFamily: F } = loadSans("normal", { weights: ["600", "700"], subsets: ["latin", "latin-ext"] });

export const AML_FPS = 30;
const OFF = 0.9;
const END = 34.13;
const CUT_TOTAL = AME3_CUTS.reduce((a, [x, y]) => a + (y - x), 0);
export const AML_FRAMES = Math.round((END - OFF - CUT_TOTAL) * AML_FPS);
const toSrc = (tv: number) => {
  let s = tv + OFF;
  for (const [a, b] of AME3_CUTS) if (s >= a) s += b - a;
  return s;
};
const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);

const GOLD_G = "linear-gradient(100deg, #F8E08A 0%, #E2B646 38%, #C9962B 72%, #F1D27A 100%)";
const COL = 840;   // largura da coluna de texto (margem de 120)

// ───────── lettering: cada frase ocupa o mesmo lugar; a anterior some inteira antes de a próxima entrar ─────────
type Ln = { w: string; at: number; gold?: boolean; sans?: boolean; size?: number };
type Phrase = { out: number; lines: Ln[] };
const PH: Phrase[] = [
  { out: 3.36, lines: [{ w: "Você já imaginou ter", at: 1.3 }, { w: "A SUA MARCA", at: 2.5, gold: true }] },
  { out: 5.3, lines: [{ w: "sendo exposta", at: 3.42 }, { w: "EM UM EVENTO", at: 4.48, gold: true }] },
  { out: 7.4, lines: [{ w: "com mais de", at: 5.36 }, { w: "180 MULHERES", at: 6.3, gold: true }] },
  { out: 10.24, lines: [{ w: "para poder comprar o seu", at: 7.62 }, { w: "PRODUTO OU SERVIÇO?", at: 8.87, gold: true }] },
  { out: 12.44, lines: [{ w: "Vem aí a", at: 11.01 }, { w: "3ª EDIÇÃO", at: 11.69, gold: true, sans: true }] },
  { out: 14.14, lines: [{ w: "PASSARELA", at: 12.57, gold: true, size: 112 }, { w: "EMPREENDEDORA", at: 13.23, gold: true, size: 80 }] },
  { out: 16.22, lines: [{ w: "A segunda foi", at: 14.33 }, { w: "UM SUCESSO", at: 15.21, gold: true }] },
  { out: 19.16, lines: [{ w: "e essa vai ser", at: 16.39 }, { w: "MELHOR AINDA", at: 18.03, gold: true }] },
  { out: 22.16, lines: [{ w: "Se você quer ganhar", at: 19.6 }, { w: "MAIS VISIBILIDADE,", at: 20.98, gold: true, size: 74 }] },
  { out: 24.04, lines: [{ w: "aumentar as", at: 22.27 }, { w: "SUAS VENDAS,", at: 23.19, gold: true }] },
  { out: 25.86, lines: [{ w: "aqui é o", at: 24.15 }, { w: "LUGAR CERTO.", at: 24.95, gold: true }] },
  { out: 27.36, lines: [{ w: "Entre em contato", at: 25.98 }, { w: "AGORA", at: 26.8, gold: true, size: 124 }] },
  { out: 29.2, lines: [{ w: "para saber", at: 27.44 }, { w: "MAIS INFORMAÇÕES", at: 27.98, gold: true }] },
  { out: 32.22, lines: [{ w: "e como você pode estar aqui,", at: 29.37 }, { w: "NESSE ESPAÇO", at: 31.25, gold: true }] },
  { out: 99, lines: [{ w: "vendendo", at: 32.3 }, { w: "O SEU PRODUTO.", at: 33.12, gold: true }] },
];
// toda frase segue o mesmo padrão (referência do o diretor, 12/10): linha branca em cima, destaque grande em Cinzel dourado
// embaixo. Tamanho que cabe na coluna (largura média por letra: Inter 0,5 · Cinzel em caixa-alta 0,72)
const fit = (l: Ln) => l.size ?? Math.min(l.gold ? 104 : 74, Math.floor(COL / (l.w.length * (l.gold && !l.sans ? 0.72 : 0.5))));

const Lettering: React.FC<{ t: number }> = ({ t }) => (
  <>
    {PH.map((p, i) => {
      const first = p.lines[0].at;
      if (t < first - 0.02 || t > p.out + 0.2) return null;
      const o = lin(t, p.out, p.out + 0.16);
      return (
        <div key={i} style={{ position: "absolute", left: 0, right: 0, top: 1330, height: 260, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 6, opacity: 1 - o, filter: o > 0 ? `blur(${(o * 12).toFixed(1)}px)` : undefined }}>
          {p.lines.map((l, j) => {
            const e = k(t, l.at, l.gold ? 0.5 : 0.4);
            const s = fit(l);
            const base: React.CSSProperties = l.gold
              ? { fontFamily: l.sans ? F : CZ, fontWeight: 700, letterSpacing: l.sans ? "-0.01em" : "0.03em", backgroundImage: GOLD_G, WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent", filter: `drop-shadow(0 4px 14px rgba(0,0,0,0.55)) blur(${((1 - e) * 14).toFixed(1)}px)` }
              : { fontFamily: F, fontWeight: 600, letterSpacing: "-0.03em", color: "#FFFFFF", textShadow: "0 3px 18px rgba(0,0,0,0.55)", filter: `blur(${((1 - e) * 14).toFixed(1)}px)` };
            return (
              <div key={j} style={{ fontSize: s, lineHeight: 1.12, whiteSpace: "nowrap", paddingBottom: s * 0.05, opacity: Math.min(1, e * 1.8), transform: `translateY(${((1 - e) * 26).toFixed(1)}px) scale(${(l.gold ? 0.9 + 0.1 * e : 1).toFixed(3)})`, ...base }}>
                {l.w}
              </div>
            );
          })}
        </div>
      );
    })}
  </>
);

// ───────── ela: aproximação diferente a cada frase (a troca cai nas emendas das pausas) ─────────
const ZOOM: [number, number, number][] = [   // início, escala inicial, escala final
  [OFF, 1.14, 1.0],
  [3.4, 1.26, 1.32],
  [7.5, 1.08, 1.16],
  [10.6, 1.34, 1.28],
  [16.25, 1.0, 1.1],
  [19.2, 1.3, 1.36],
  [22.2, 1.12, 1.18],
  [24.06, 1.4, 1.34],
  [25.9, 1.06, 1.14],
  [27.4, 1.28, 1.34],
  [29.25, 1.1, 1.2],
  [32.24, 1.0, 1.1],
  [END + 1, 1, 1],
];
const Her: React.FC<{ t: number }> = ({ t }) => {
  let i = 0;
  while (i < ZOOM.length - 2 && t >= ZOOM[i + 1][0]) i++;
  const s = interpolate(t, [ZOOM[i][0], ZOOM[i + 1][0]], [ZOOM[i][1], ZOOM[i][2]], cl);
  return (
    <AbsoluteFill style={{ transform: `scale(${s.toFixed(4)})`, transformOrigin: "50% 26%" }}>
      <OffthreadVideo src={staticFile("ame/ame3-cut.mp4")} muted style={{ width: "100%", height: "100%", objectFit: "cover" }} />
    </AbsoluteFill>
  );
};

// ───────── fotos do evento em tela cheia: a foto inteira, sobre ela mesma desfocada, com aproximação lenta ─────────
type Ph = { id: string; a: number; b: number; ar: number; y?: number; dir?: 1 | -1 };
const FOTOS: Ph[] = [
  { id: "ev-plateia", a: 5.3, b: 7.42, ar: 960 / 720, y: 470 },
  { id: "a3-desfile", a: 12.5, b: 14.16, ar: 912 / 1408, dir: -1 },
  { id: "a3-dupla1", a: 14.16, b: 14.9, ar: 936 / 1600 },
  { id: "a3-trio", a: 14.9, b: 15.56, ar: 1200 / 1600, y: 200, dir: -1 },
  { id: "a3-palco", a: 15.56, b: 16.25, ar: 900 / 1600 },
  { id: "a3-dupla2", a: 30.86, b: 32.24, ar: 1080 / 1600, dir: -1 },
];
const Foto: React.FC<{ t: number; p: Ph; soft: boolean }> = ({ t, p, soft }) => {
  const h = 1080 / p.ar;
  const u = lin(t, p.a, p.b);
  const e = soft ? k(t, p.a, 0.35) : 1;
  const top = p.y ?? (1920 - h) / 2;
  return (
    <AbsoluteFill style={{ background: "#000", opacity: Math.min(1, e * 1.6) }}>
      <Img src={staticFile(`ame/${p.id}.jpg`)} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", filter: "blur(40px) brightness(0.5)", transform: "scale(1.2)" }} />
      <div style={{ position: "absolute", left: 0, top, width: 1080, height: h, overflow: "hidden", transform: `scale(${(1.12 - 0.08 * e + 0.05 * u).toFixed(4)}) translateX(${((p.dir ?? 1) * (u - 0.5) * 22).toFixed(1)}px)` }}>
        <Img src={staticFile(`ame/${p.id}.jpg`)} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
      </div>
    </AbsoluteFill>
  );
};

export const AmeLettering: React.FC = () => {
  const t = toSrc(useCurrentFrame() / AML_FPS);
  const tagIn = k(t, 14.2, 0.6);
  return (
    <AbsoluteFill style={{ background: "#000" }}>
      <Her t={t} />
      {FOTOS.map((p, i) => (t >= p.a && t < p.b ? <Foto key={p.id} t={t} p={p} soft={i === 0 || FOTOS[i - 1].b !== p.a} /> : null))}
      {/* sombra em degradê: leve em cima, mais presente embaixo, onde fica o lettering */}
      <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(0,0,0,0.62) 0px, rgba(0,0,0,0.4) 240px, rgba(0,0,0,0) 560px)" }} />
      <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(0,0,0,0) 980px, rgba(0,0,0,0.42) 1280px, rgba(0,0,0,0.74) 1560px, rgba(0,0,0,0.86) 1920px)" }} />
      {/* assinatura do evento em cima, depois que ela diz o nome */}
      <div style={{ position: "absolute", left: 0, right: 0, top: 150, display: "flex", flexDirection: "column", alignItems: "center", gap: 14, opacity: tagIn, transform: `translateY(${((1 - tagIn) * -20).toFixed(1)}px)` }}>
        <div style={{ fontFamily: CZ, fontWeight: 700, fontSize: 36, letterSpacing: "0.14em", whiteSpace: "nowrap", backgroundImage: GOLD_G, WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent", filter: "drop-shadow(0 2px 10px rgba(0,0,0,0.6))" }}>PASSARELA EMPREENDEDORA</div>
        <div style={{ width: 300 * tagIn, height: 2, background: "#E2B646", opacity: 0.8 }} />
        <div style={{ fontFamily: F, fontWeight: 600, fontSize: 30, letterSpacing: "0.22em", color: "#FFFFFF", textShadow: "0 2px 10px rgba(0,0,0,0.6)" }}>3ª EDIÇÃO</div>
      </div>
      <Lettering t={t} />
    </AbsoluteFill>
  );
};

import { loadFont as loadSerif } from "@remotion/google-fonts/Cinzel";
import { loadFont as loadSans } from "@remotion/google-fonts/Inter";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, interpolate, staticFile, useCurrentFrame } from "remotion";

// AME · convite para a 3ª edição do Passarela Empreendedora. Vertical, 33,2 s. Vídeo novo (11/10), com a fala nova dela.
// O áudio é a fala dela, inteira e sem corte (só sai o silêncio do começo); a imagem intercala ela (6 trechos) com cenas
// em motion (7). Identidade da AME (pedido do cliente): preto, dourado da formiga, vermelho-escuro do "AME", Cinzel só nos
// nomes, Inter no resto. Fotos da edição anterior recortadas sem as marcas de terceiros (patrocinadores, telão da loja).
// O vídeo dela veio em HDR e foi convertido com avconvert (public/ame/ame3.mp4). Todos os tempos = tempo da fala no vídeo.

const { fontFamily: CZ } = loadSerif("normal", { weights: ["600", "700"], subsets: ["latin", "latin-ext"] });
const { fontFamily: F } = loadSans("normal", { weights: ["500", "600", "700"], subsets: ["latin", "latin-ext"] });

export const AME3_FPS = 30;
const OFF = 0.9;            // o vídeo começa aqui (antes é silêncio)
const END = 34.13;          // fim do áudio dela
// pausas da fala retiradas (pedido, 11/10): trechos do vídeo original que saem. O vídeo dela já vem cortado
// (public/ame/ame3-cut.mp4, feito por tools/make_audio_ame3.py --video); as animações continuam no tempo original.
export const AME3_CUTS: [number, number][] = [[4.28, 4.38], [7.42, 7.59], [10.26, 10.94], [13.96, 14.1], [16.02, 16.13], [20.32, 20.46], [23.9, 24.03], [24.61, 24.72], [25.72, 25.83], [29.69, 29.8], [32.04, 32.2]];
const CUT_TOTAL = AME3_CUTS.reduce((a, [x, y]) => a + (y - x), 0);
export const AME3_FRAMES = Math.round((END - OFF - CUT_TOTAL) * AME3_FPS);
// tempo do vídeo final → tempo da fala no vídeo original
const toSrc = (tv: number) => {
  let s = tv + OFF;
  for (const [a, b] of AME3_CUTS) if (s >= a) s += b - a;
  return s;
};
const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.4));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);

const BLACK = "#000000";
const PAPER = "#F6F3EE";
const INK = "#1B1A19";
const GRAY = "#8A857D";
const RED = "#9B1118";
const GOLD = "#E2B646";
const GOLD_G = "linear-gradient(100deg, #F8E08A 0%, #E2B646 38%, #B8851F 72%, #F1D27A 100%)";
const CARD_D = "#161617";
const SHADOW = "0 30px 70px rgba(40,25,10,0.12), 0 4px 14px rgba(40,25,10,0.05)";

// início de cada trecho (H = ela, M = motion)
const S = { h1: OFF, m1: 3.0, h2: 7.6, m2: 10.26, m2b: 12.5, m3: 14.2, h3: 16.3, m4: 19.27, h4: 24.1, m5: 25.95, h5: 29.25, m6: 30.9, h6: 32.27 };

const blurIn = (t: number, at: number, out?: number, d = 0.5): React.CSSProperties => {
  const e = k(t, at, d);
  const o = out === undefined ? 0 : lin(t, out, out + 0.22);
  return { opacity: Math.min(1, e * 1.6) * (1 - o), filter: `blur(${((1 - e) * 22 + o * 16).toFixed(1)}px)`, transform: `translateY(${((1 - e) * 34 - o * 18).toFixed(1)}px)` };
};
const grad = (g: string): React.CSSProperties => ({ backgroundImage: g, WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent" });

type L = { w: string; at: number; hl?: boolean; cz?: boolean; size?: number; soft?: boolean };
// bloco de texto centralizado: cada linha entra desfocada no seu tempo e fica parada
const Lines: React.FC<{ t: number; items: L[]; size: number; top: number; dark?: boolean; out?: number }> = ({ t, items, size, top, dark, out }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center" }}>
    {items.map((l, i) => {
      const s = l.size ?? size;
      const base: React.CSSProperties = l.cz
        ? { fontFamily: CZ, fontWeight: 700, letterSpacing: "0.02em", lineHeight: 1.12, ...grad(GOLD_G) }
        : { fontFamily: F, fontWeight: 600, letterSpacing: "-0.035em", lineHeight: 1.1, color: l.soft ? (dark ? "rgba(255,255,255,0.72)" : GRAY) : dark ? "#FFFFFF" : INK, ...(l.hl ? (dark ? grad(GOLD_G) : { color: RED }) : {}) };
      return <div key={i} style={{ fontSize: s, whiteSpace: "nowrap", paddingBottom: s * 0.07, ...base, ...blurIn(t, l.at, out) }}>{l.w}</div>;
    })}
  </div>
);

// ───────── ícones ─────────
const IcoPerson: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 48 48" fill={c}><circle cx={24} cy={18} r={8.5} /><path d="M8 43c0-9 7-14.5 16-14.5S40 34 40 43z" /></svg>
);
const IcoStar: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 48 48" fill={c}><path d="M24 4l5.9 12.6 13.6 1.7-10 9.5 2.6 13.7L24 34.7 11.9 41.5l2.6-13.7-10-9.5 13.6-1.7z" /></svg>
);
const IcoEye: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 48 48" fill="none" stroke={c} strokeWidth={3.2} strokeLinecap="round" strokeLinejoin="round"><path d="M4 24s7.5-13 20-13 20 13 20 13-7.5 13-20 13S4 24 4 24z" /><circle cx={24} cy={24} r={6.5} fill={c} /></svg>
);
const IcoBag: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 48 48" fill="none" stroke={c} strokeWidth={3.4} strokeLinecap="round" strokeLinejoin="round"><path d="M9 16h30l-2.5 26h-25z" /><path d="M17 20v-6a7 7 0 0 1 14 0v6" /></svg>
);
const IcoChat: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 48 48" fill={c}><path d="M24 6C13 6 5 13.4 5 22.5c0 4.6 2 8.700 5.4 11.700L8.500 42l9-4c2 .6 4.200 1 6.500 1 11 0 19-7.400 19-16.500S35 6 24 6z" /></svg>
);

// ───────── ela: o vídeo inteiro, com aproximação diferente a cada trecho ─────────
type Cap = { w: string; at: number; gold?: boolean };
const Her: React.FC<{ t: number; a: number; b: number; z: [number, number]; oy?: number; caps: Cap[] }> = ({ t, a, b, z, oy = 24, caps }) => {
  const s = interpolate(t, [a, b], z, cl);
  return (
    <AbsoluteFill style={{ background: BLACK }}>
      <AbsoluteFill style={{ transform: `scale(${s.toFixed(4)})`, transformOrigin: `50% ${oy}%` }}>
        <OffthreadVideo src={staticFile("ame/ame3-cut.mp4")} muted style={{ width: "100%", height: "100%", objectFit: "cover" }} />
      </AbsoluteFill>
      <div style={{ position: "absolute", left: 0, right: 0, top: 1392, display: "flex", flexDirection: "column", alignItems: "center", gap: 16 }}>
        {caps.map((c, i) => (
          <div key={i} style={{ padding: "16px 38px 18px", borderRadius: 30, background: "rgba(8,8,8,0.9)", fontFamily: F, fontWeight: 600, fontSize: 58, letterSpacing: "-0.03em", lineHeight: 1.1, whiteSpace: "nowrap", opacity: Math.min(1, k(t, c.at, 0.4) * 1.8), transform: `translateY(${((1 - k(t, c.at, 0.45)) * 40).toFixed(1)}px) scale(${(0.9 + 0.1 * pop(t, c.at, 0.45)).toFixed(3)})` }}>
            <span style={c.gold ? grad(GOLD_G) : { color: "#FFFFFF" }}>{c.w}</span>
          </div>
        ))}
      </div>
    </AbsoluteFill>
  );
};

// ───────── M1 · a sua marca exposta para mais de 180 mulheres (claro) ─────────
const RING: [number, number, number][] = [   // raio, quantidade, início
  [215, 8, 4.2],
  [330, 14, 5.0],
];
const Vitrine: React.FC<{ t: number }> = ({ t }) => {
  const B = 4.78;
  const cardIn = pop(t, S.m1 + 0.05, 0.6);
  const flash = interpolate(t, [3.66, 3.72, 4.1], [0, 1, 0], cl);
  return (
    <AbsoluteFill style={{ background: PAPER }}>
      {t < B + 0.3 ? <Lines t={t} top={330} size={124} out={B - 0.12} items={[{ w: "A sua marca", at: S.m1 + 0.02 }, { w: "exposta", at: 3.66, hl: true }]} /> : null}
      {t >= B ? <Lines t={t} top={250} size={100} items={[{ w: "num evento com mais de", at: 4.84, size: 58, soft: true }, { w: "180", at: 6.3, hl: true, size: 230 }, { w: "mulheres", at: 6.88 }]} /> : null}
      <div style={{ position: "absolute", left: 120, top: 820 + Math.sin(t * 2.2) * 8, width: 840, height: 700, borderRadius: 60, background: "#FFFFFF", boxShadow: SHADOW, overflow: "hidden", opacity: Math.min(1, cardIn * 2), transform: `translateY(${((1 - cardIn) * 220).toFixed(1)}px) scale(${(0.92 + 0.08 * cardIn + 0.05 * lin(t, S.m1, S.h2)).toFixed(4)})` }}>
        {/* holofote do flash em "exposta" */}
        <div style={{ position: "absolute", left: 420 - 300, top: 350 - 300, width: 600, height: 600, borderRadius: 300, background: `radial-gradient(circle, rgba(226,182,70,${(0.1 + 0.35 * flash).toFixed(2)}) 0%, rgba(226,182,70,0) 70%)` }} />
        {RING.map(([r, n, at], ri) =>
          [...Array(n)].map((_, i) => {
            const a = (i / n) * Math.PI * 2 + ri * 0.2 + (t - S.m1) * (ri ? -0.12 : 0.16);
            const e = pop(t, at + i * 0.045, 0.4);
