// ───────── montagem: ela e o motion se alternam, cada troca de um jeito ─────────
type Kind = "none" | "sheet" | "zoom" | "cut" | "shutter" | "pushL" | "drop" | "iris" | "pushU" | "diag" | "doors" | "pushR" | "blur";
const enter = (kind: Kind, p: number): React.CSSProperties => {
  switch (kind) {
    case "sheet": return { transform: `translateY(${((1 - p) * 1920).toFixed(1)}px)`, borderRadius: `${((1 - p) * 90).toFixed(0)}px ${((1 - p) * 90).toFixed(0)}px 0 0`, overflow: "hidden" };
    case "zoom": return { opacity: Math.min(1, p * 1.7), transform: `scale(${(1.3 - 0.3 * p).toFixed(4)})`, filter: `blur(${((1 - p) * 18).toFixed(1)}px)` };
    case "shutter": return { clipPath: `inset(${((1 - p) * 50).toFixed(2)}% 0 ${((1 - p) * 50).toFixed(2)}% 0)` };
    case "pushL": return { transform: `translateX(${((1 - p) * 1080).toFixed(1)}px)` };
    case "pushR": return { transform: `translateX(${(-(1 - p) * 1080).toFixed(1)}px)` };
    case "pushU": return { transform: `translateY(${((1 - p) * 1920).toFixed(1)}px)` };
    case "drop": return { transform: `translateY(${(-(1 - p) * 1920).toFixed(1)}px)`, borderRadius: `0 0 ${((1 - p) * 90).toFixed(0)}px ${((1 - p) * 90).toFixed(0)}px`, overflow: "hidden" };
    case "iris": return { clipPath: `circle(${(p * 2300).toFixed(0)}px at 540px 820px)` };
    case "diag": { const x = p * 1900; return { clipPath: `polygon(0px 0px, ${x.toFixed(0)}px 0px, ${(x - 820).toFixed(0)}px 1920px, 0px 1920px)` }; }
    case "doors": return { clipPath: `inset(0 ${((1 - p) * 50).toFixed(2)}% 0 ${((1 - p) * 50).toFixed(2)}%)` };
    case "blur": return { opacity: p, filter: `blur(${((1 - p) * 22).toFixed(1)}px)` };
    default: return {};
  }
};
const leave = (kind: Kind, p: number): React.CSSProperties => {
  switch (kind) {
    case "pushL": return { transform: `translateX(${(-p * 1080).toFixed(1)}px)` };
    case "pushR": return { transform: `translateX(${(p * 1080).toFixed(1)}px)` };
    case "pushU": return { transform: `translateY(${(-p * 1920).toFixed(1)}px)` };
    case "sheet": case "drop": return { transform: `scale(${(1 - 0.06 * p).toFixed(4)})` };
    default: return {};
  }
};

